 12	static void UI_DrawLogo(uint16_t x0, uint16_t y0)
 13	{
 14	    uint32_t width = BSP_LCD_GetXSize();
 15	    uint32_t *fb = (uint32_t *)LCD_FB_START_ADDRESS;
 16	
 17	    for (uint32_t r = 0; r < LOGO_PTIT_HEIGHT; r++) {
 18	        for (uint32_t c = 0; c < LOGO_PTIT_WIDTH; c++) {
 19	            uint32_t color = logo_ptit_data[r * LOGO_PTIT_WIDTH + c];
 20	            if ((color & 0xFF000000) != 0) {
 21	                fb[(y0 + r) * width + (x0 + c)] = color;
 22	            }
 23	        }
 24	    }
 25	}
